import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import path from 'path'
import fs from 'fs'

const PRIME_REACT_IMPORT_REGEX = /['"]primereact\/([^'"]+)['"]/gi
const SCANNABLE_EXTENSIONS = /\.(cjs|mjs|js|jsx|ts|tsx|md|mdx)$/

const srcDirectory = path.resolve(__dirname, './src')
const primeReactDeps = collectPrimeReactModules(srcDirectory)

function collectPrimeReactModules(targetDir) {
  const modules = new Set()

  const visit = (dir) => {
    let entries = []

    try {
      entries = fs.readdirSync(dir, { withFileTypes: true })
    } catch (error) {
      console.warn(`[vite] Unable to read directory ${dir}:`, error.message)
      return
    }

    for (const entry of entries) {
      const absolutePath = path.join(dir, entry.name)

      if (entry.isDirectory()) {
        visit(absolutePath)
        continue
      }

      if (!SCANNABLE_EXTENSIONS.test(entry.name)) {
        continue
      }

      let content = ''
      try {
        content = fs.readFileSync(absolutePath, 'utf-8')
      } catch (error) {
        console.warn(`[vite] Unable to read file ${absolutePath}:`, error.message)
        continue
      }

      let match
      while ((match = PRIME_REACT_IMPORT_REGEX.exec(content)) !== null) {
        const specifier = sanitizeSpecifier(match[1])

        if (!specifier || specifier.startsWith('images/')) {
          continue
        }

        modules.add(`primereact/${specifier}`)
      }
    }
  }

  visit(targetDir)
  return Array.from(modules).sort()
}

function sanitizeSpecifier(rawSpecifier = '') {
  const cleaned = rawSpecifier
    .replace(/\\/g, '/')
    .replace(/\?.*/, '')
    .replace(/\/+/g, '/')
    .replace(/^\//, '')
    .trim()

  if (!cleaned) {
    return ''
  }

  // Allow only url-safe characters
  if (!/^[0-9a-z/-]+$/i.test(cleaned)) {
    return ''
  }

  return cleaned.toLowerCase()
}

// https://vite.dev/config/
export default defineConfig({
  
  plugins: [
    react(),
  ],
  optimizeDeps: {
    include: primeReactDeps
  },
  css: {
    preprocessorOptions: {
      less: {
        // Enable LESS processing
        javascriptEnabled: true,
        // Add paths for LESS imports
        // LESS resolves imports relative to these paths
        paths: [
          path.resolve(__dirname, './src/styles'),
          path.resolve(__dirname, '../../../src/styles'), // ULS styles root - allows "uls-styles/less/..." imports from uls.less
        ]
      }
    }
  },
  resolve: {
    alias: {
      '@uls-styles': path.resolve(__dirname, '../../../dist/css'),
      '@uls-button-demo': path.resolve(__dirname, './src/Components/Demo/Button/ButtonFeatures'),
      '@uls/foundation': path.resolve(__dirname, '../uls-foundation/src'),
      '@uls/components': path.resolve(__dirname, '../../../src/uls-components/src'),
      primereact: path.resolve(__dirname, '../../../node_modules/primereact'),
      'primereact/utils': path.resolve(__dirname, '../../../node_modules/primereact/utils'),
      'primereact/api': path.resolve(__dirname, '../../../node_modules/primereact/api')
    }
  },
})
